USE aerosoft360_rebuild;
CREATE TABLE IF NOT EXISTS article_set_templates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,article_id BIGINT UNSIGNED NOT NULL,name VARCHAR(100) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'active',created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,UNIQUE KEY article_set_name(article_id,name),FOREIGN KEY(article_id) REFERENCES articles(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS article_set_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,set_template_id BIGINT UNSIGNED NOT NULL,size_label VARCHAR(30) NOT NULL,quantity DECIMAL(8,2) NOT NULL,unit_price DECIMAL(18,2) NOT NULL,sort_order SMALLINT UNSIGNED NOT NULL DEFAULT 0,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,UNIQUE KEY set_size_unique(set_template_id,size_label),FOREIGN KEY(set_template_id) REFERENCES article_set_templates(id) ON DELETE CASCADE) ENGINE=InnoDB;
ALTER TABLE customer_po_lines ADD COLUMN IF NOT EXISTS set_template_id BIGINT UNSIGNED NULL AFTER article_id;
ALTER TABLE receipt_allocations ADD COLUMN IF NOT EXISTS commission_rate DECIMAL(18,2) NOT NULL DEFAULT 0 AFTER days_taken;
INSERT IGNORE INTO article_set_templates(article_id,name,status,created_at,updated_at) SELECT id,set_name,'active',NOW(),NOW() FROM articles;
INSERT IGNORE INTO article_set_items(set_template_id,size_label,quantity,unit_price,sort_order,created_at,updated_at) SELECT t.id,s.size_label,s.pieces_per_set,a.selling_price,s.sort_order,NOW(),NOW() FROM article_set_templates t JOIN articles a ON a.id=t.article_id JOIN article_sizes s ON s.article_id=a.id;
